examples.template:
if (!dismissed) {
    MonarchCalloutBanner(
        message = {{message}},
        tone = MonarchTone.Accent,
        icon = null,
        placement = MonarchCalloutBannerPlacement.Page,
        action = {
            MonarchLink(
                text = {{action.label}},
                onClick = { /* Open the notes. */ },
                trailingIcon = { MonarchIcon(imageVector = SampleIcons.ArrowForward, contentDescription = null) },
            )
        },
        onDismiss = { dismissed = true },
    )
}

